289			t.Fatalf("reversed added = %+v, want forward removed %+v", reverse.Added, forward.Removed)
290		}
291		if !reflect.DeepEqual(reverse.Removed, forward.Added) {
292			t.Fatalf("reversed removed = %+v, want forward added %+v", reverse.Removed, forward.Added)
293		}
294		if len(reverse.Changed) != len(forward.Changed) {
295			t.Fatalf("reversed changed = %+v, want %d entries", reverse.Changed, len(forward.Changed))
296		}
297		for i, ch := range forward.Changed {
298			got := reverse.Changed[i]
299			if got.Coordinate != ch.Coordinate {
300				t.Fatalf("changed order differs at %d: %q vs %q", i, got.Coordinate, ch.Coordinate)
301			}
302			if !reflect.DeepEqual(got.Before, ch.After) || !reflect.DeepEqual(got.After, ch.Before) {
303				t.Fatalf("changed %s not flipped:\nforward: %+v\nreverse: %+v", ch.Coordinate, ch, got)
304			}
305		}
