326	// leaves its inputs untouched, later mutations of the inputs cannot change an
327	// already returned result, and mutating a result cannot affect the inputs or
328	// another call's result.
329	func TestCompareDoesNotShareMemory(t *testing.T) {
330		before, after := mustParse(t, compareV1), mustParse(t, compareV2)
331		beforeSnapshot := mustParse(t, compareV1)
332		afterSnapshot := mustParse(t, compareV2)
333	
334		first := mustCompare(t, before, after)
335		firstSnapshot := mustCompare(t, before, after)
336	
337		// Mutating the result must not reach the inputs or a fresh comparison.
338		first.Added[0].License = "MUTATED"
339		first.Added[0].Dependencies = append(first.Added[0].Dependencies, "MUTATED")
340		first.Removed[0].License = "MUTATED"
341		first.Changed[0].Before.License = "MUTATED"
342		first.Changed[0].After.Dependencies[0] = "MUTATED"
343		if !reflect.DeepEqual(*before, *beforeSnapshot) || !reflect.DeepEqual(*after, *afterSnapshot) {
344			t.Fatalf("result mutation leaked into inputs:\nbefore: %#v\nafter:  %#v", before, after)
345		}
346		second := mustCompare(t, before, after)
347		if !reflect.DeepEqual(second, firstSnapshot) {
348			t.Fatalf("result mutation affected a later call:\ngot:  %#v\nwant: %#v", second, firstSnapshot)
349		}
350	
351		// Mutating the inputs afterwards must not rewrite the returned result.
352		before.Components[0].License = "MUTATED"
353		before.Components[0].Dependencies[0] = "MUTATED"
354		after.Components[0].Coordinate = "MUTATED"
355		if !reflect.DeepEqual(second, firstSnapshot) {
356			t.Fatalf("input mutation changed the returned result:\ngot:  %#v\nwant: %#v", second, firstSnapshot)
357		}
358	}
