16	// The same manifest twice: padded with whitespace and shuffled arrays, then
17	// the canonical ordering. Both entry points must derive identical content.
18	const sharedMessy = `{"artifact":" app ","version":" 1 ","components":[
19		{"coordinate":"c","license":" L3 ","dependencies":[]},
20		{"coordinate":"a","license":"L1","dependencies":["c","b"]},
21		{"coordinate":"b","license":"L2","dependencies":["c"]}
22	]}`
23	
24	const sharedShuffled = `{"artifact":"app","version":"1","components":[
25		{"coordinate":"b","license":"L2","dependencies":["c"]},
26		{"coordinate":"c","license":"L3","dependencies":[]},
27		{"coordinate":"a","license":"L1","dependencies":["b","c"]}
28	]}`
29	
30	// TestStandaloneParseAndHTTPRegistrationShareNormalization proves the two
31	// callers apply one rule set: the library entry and POST /sboms turn the
32	// padded, out-of-order payload into the same normalized content; replaying the
33	// shuffled variant still returns 201 with the original id.
34	func TestStandaloneParseAndHTTPRegistrationShareNormalization(t *testing.T) {
35		router, _ := newTestRouter(t)
36	
37		parsed, err := manifest.ParseRegistration([]byte(sharedMessy))
38		if err != nil {
39			t.Fatalf("standalone parse: %v", err)
40		}
41		if parsed.ID != 0 {
42			t.Fatalf("parsed id = %d, want zero before registration", parsed.ID)
43		}
44	
45		rec := postSBOM(t, router, sharedMessy)
46		if rec.Code != http.StatusCreated {
47			t.Fatalf("register messy: %d %s", rec.Code, rec.Body.String())
48		}
49		var registered model.SBOM
50		decodeBody(t, rec, &registered)
51		if registered.ID <= 0 {
52			t.Fatalf("registered id = %d, want store-assigned positive id", registered.ID)
53		}
54	
55		// Same normalization, minus the store-assigned id.
56		parsed.ID = registered.ID
57		if !reflect.DeepEqual(*parsed, registered) {
58			t.Fatalf("standalone vs HTTP content differs:\n%#v\n%#v", parsed, registered)
59		}
60	
61		// Shuffled, re-padded replay: still 201 and the same record.
62		rec = postSBOM(t, router, sharedShuffled)
63		if rec.Code != http.StatusCreated {
64			t.Fatalf("replay shuffled: %d %s", rec.Code, rec.Body.String())
65		}
66		var replayed model.SBOM
67		decodeBody(t, rec, &replayed)
68		if replayed.ID != registered.ID {
69			t.Fatalf("replay id = %d, want %d", replayed.ID, registered.ID)
70		}
71		if !reflect.DeepEqual(replayed, registered) {
72			t.Fatalf("replay content differs:\n%#v\n%#v", replayed, registered)
73		}
74	
75		// GET /sboms returns the same normalized record, so the stored
76		// reconstruction follows the identical rule too.
77		pageRec := getSBOMs(t, router, "/sboms?artifact=app")
78		var page listResponse
79		decodeBody(t, pageRec, &page)
80		if page.Total != 1 || len(page.Items) != 1 {
81			t.Fatalf("page = total %d items %d, want 1/1", page.Total, len(page.Items))
82		}
83		if !reflect.DeepEqual(*page.Items[0], registered) {
84			t.Fatalf("listed manifest differs from registered:\n%#v\n%#v", page.Items[0], registered)
85		}
86	}
87	
88	// TestParsedManifestRegistersThroughStore shows the intended Go workflow: the
89	// zero-id parse result is handed to the store as-is, and idempotency and
90	// conflict behavior match the HTTP entry.
91	func TestParsedManifestRegistersThroughStore(t *testing.T) {
92		router, st := newTestRouter(t)
93	
94		first, err := manifest.ParseRegistration([]byte(sharedMessy))
95		if err != nil {
96			t.Fatalf("first parse: %v", err)
97		}
98		saved, created, err := st.Register(t.Context(), first)
99		if err != nil || !created {
100			t.Fatalf("register parsed: err=%v created=%v", err, created)
101		}
102		if saved.ID <= 0 || first.ID != 0 {
103			t.Fatalf("store must assign id onto its own result, parse result stays zero-id: saved=%d input=%d",
104				saved.ID, first.ID)
105		}
106	
107		// A second, independently parsed copy of the same bytes is recognized as
108		// the same manifest: same id, created=false.
109		again, err := manifest.ParseRegistration([]byte(sharedShuffled))
110		if err != nil {
111			t.Fatalf("second parse: %v", err)
112		}
113		replayed, created, err := st.Register(t.Context(), again)
114		if err != nil || created {
115			t.Fatalf("re-register parsed: err=%v created=%v", err, created)
116		}
117		if replayed.ID != saved.ID {
118			t.Fatalf("id = %d, want %d", replayed.ID, saved.ID)
119		}
120	
121		// License change and direct-dependency change parsed standalone both
122		// conflict and leave the stored record untouched.
123		mutated := []string{
